 public sealed class RecoveryItem{public string ProjectPath,Snapshot,Name;public DateTime Time;public override string ToString(){return Name+"  ·  "+Time.ToLocalTime().ToString("g");}}
 public sealed class RecoveryStore
 {
  private string _folder;private int _slot;private string _last;public RecoveryStore(string root){_folder=Path.Combine(root,"Recovery",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(_folder);}
  public void Snapshot(ProjectDocument project,string path){string json=ProjectFile.Serialize(project);if(json==_last)return;string file=Path.Combine(_folder,(_slot++%3)+".slopdaw");ProjectFile.SaveAtomic(project,file,false);File.WriteAllText(Path.Combine(_folder,"session.json"),new JavaScriptSerializer().Serialize(new {Name=project.Name,ProjectPath=path,Pid=System.Diagnostics.Process.GetCurrentProcess().Id,Latest=file}),new System.Text.UTF8Encoding(false));_last=json;}
  public void Close(){File.WriteAllText(Path.Combine(_folder,"closed"),DateTime.UtcNow.ToString("O"));}
  public static List<RecoveryItem> Find(string root){var result=new List<RecoveryItem>();string folder=Path.Combine(root,"Recovery");if(!Directory.Exists(folder))return result;foreach(string session in Directory.GetDirectories(folder)){if(File.Exists(Path.Combine(session,"closed")))continue;try{var j=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(session,"session.json")));int pid=Convert.ToInt32(j["Pid"]);try{if(pid>0&&!System.Diagnostics.Process.GetProcessById(pid).HasExited)continue;}catch{}string snapshot=Convert.ToString(j["Latest"]);if(!File.Exists(snapshot)||!Path.GetFullPath(snapshot).StartsWith(Path.GetFullPath(session)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))continue;ProjectFile.Load(snapshot);result.Add(new RecoveryItem{Name=Convert.ToString(j["Name"]),ProjectPath=Convert.ToString(j["ProjectPath"]),Snapshot=snapshot,Time=File.GetLastWriteTimeUtc(snapshot)});}catch{}}return result.OrderByDescending(i=>i.Time).ToList();}
 }
