 public sealed class AudioExportDialog:Form
 {
  private readonly ProjectDocument _project;private StudioChoice _format,_rate,_scope;private NumericUpDown _start,_end,_tail;private ProgressBar _progress;private Label _status;private Button _render;private CancellationTokenSource _cancel;private bool _busy;
  public AudioExportDialog(ProjectDocument project){_project=ProjectFactory.Clone(project);Text="Master Project or Selection";ClientSize=new Size(610,410);BackColor=Color.FromArgb(59,59,60);ForeColor=Color.Gainsboro;Font=new Font("Segoe UI",9);StartPosition=FormStartPosition.CenterParent;var table=new TableLayoutPanel{Dock=DockStyle.Top,Padding=new Padding(18),ColumnCount=2,RowCount=6,Height=294};table.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,190));table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));_format=Combo(new object[]{"WAV · 16-bit PCM","WAV · 24-bit PCM","WAV · 32-bit float","MP3 · 320 kbps (FFmpeg)"},1);_rate=Combo(new object[]{22050,44100,48000,88200,96000},2);_scope=Combo(new object[]{"Stereo mix","Individual track stems"},0);double last=project.Tracks.SelectMany(t=>t.Regions).Select(r=>r.StartBeat+r.LengthBeats).DefaultIfEmpty(16).Max();_start=Number(0,1000000,project.CycleEnabled?project.CycleStartBeat:0);_end=Number(.0625m,1000000,project.CycleEnabled?project.CycleEndBeat:last);_tail=Number(0,60,1);Control[] controls={_format,_rate,_scope,_start,_end,_tail};string[] labels={"File format","Sample rate","Output","Start (beats from zero)","End (beats from zero)","Tail (seconds)"};for(int i=0;i<6;i++){table.RowStyles.Add(new RowStyle(SizeType.Absolute,42));table.Controls.Add(new Label{Text=labels[i],Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleRight},0,i);table.Controls.Add(controls[i],1,i);}_progress=new ProgressBar{Dock=DockStyle.Bottom,Height=14};_status=new Label{Dock=DockStyle.Bottom,Height=29,TextAlign=ContentAlignment.MiddleLeft,Text="Offline rendering uses the real instrument and plug-in graph."};_render=new Button{Text="Export Master…",Dock=DockStyle.Right,Width=120,FlatStyle=FlatStyle.Flat};_render.Click+=delegate{Start();};var cancel=new Button{Text="Cancel",Dock=DockStyle.Right,Width=110,FlatStyle=FlatStyle.Flat};cancel.Click+=delegate{if(_busy){_cancel.Cancel();_status.Text="Cancelling…";}else Close();};var footer=new Panel{Dock=DockStyle.Bottom,Height=43,Padding=new Padding(5)};footer.Controls.Add(cancel);footer.Controls.Add(_render);Controls.Add(table);Controls.Add(_progress);Controls.Add(_status);Controls.Add(footer);FormClosing+=delegate(object s,FormClosingEventArgs e){if(_busy){e.Cancel=true;_cancel.Cancel();}};}
  private StudioChoice Combo(object[] items,int selected){var c=new StudioChoice{DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Fill};c.Items.AddRange(items);c.SelectedIndex=selected;return c;}
  private NumericUpDown Number(decimal min,decimal max,double value){return new NumericUpDown{Minimum=min,Maximum=max,DecimalPlaces=3,Value=Math.Max(min,Math.Min(max,(decimal)value)),Dock=DockStyle.Fill,BackColor=Color.FromArgb(43,43,44),ForeColor=Color.Gainsboro,BorderStyle=BorderStyle.FixedSingle};}
  private void Start(){if(_busy)return;var options=new AudioExportOptions{SampleRate=Convert.ToInt32(_rate.SelectedItem),Bits=_format.SelectedIndex==0?16:_format.SelectedIndex==2?32:24,Float=_format.SelectedIndex==2,StartBeat=(double)_start.Value,EndBeat=(double)_end.Value,TailSeconds=(double)_tail.Value};bool stems=_scope.SelectedIndex==1,mp3=_format.SelectedIndex==3;string path;if(stems){if(_project.Tracks.Count==0){MessageBox.Show(this,UiText.Translate("No tracks to export."));return;}using(var d=new FolderBrowserDialog())if(d.ShowDialog(this)==DialogResult.OK){string name=_project.Name;foreach(char c in Path.GetInvalidFileNameChars())name=name.Replace(c,'_');try{path=Path.Combine(d.SelectedPath,name+" - Stems "+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8));Directory.CreateDirectory(path);}catch(Exception ex){MessageBox.Show(this,ex.Message,UiText.Translate("Stem export failed"));return;}}else return;}else{using(var d=new SaveFileDialog{Filter=mp3?"MP3 audio|*.mp3":"WAV audio|*.wav",FileName=_project.Name+(mp3?".mp3":".wav")})if(d.ShowDialog(this)==DialogResult.OK)path=d.FileName;else return;}_busy=true;_render.Enabled=false;_cancel=new CancellationTokenSource();_status.Text="Rendering…";Task.Factory.StartNew(delegate{Exception error=null;try{var tracks=stems?_project.Tracks:new List<Track>{null};for(int i=0;i<tracks.Count;i++){ProjectDocument p=stems?AudioExport.StemProject(_project,tracks[i].Id):ProjectFactory.Clone(_project);string target=path;if(stems){string name=tracks[i].Name;foreach(char c in Path.GetInvalidFileNameChars())name=name.Replace(c,'_');target=Path.Combine(path,(i+1).ToString("00")+"-"+name+(mp3?".mp3":".wav"));}int index=i;Action<double> progress=delegate(double value){if(!IsDisposed)BeginInvoke((Action)delegate{_progress.Value=Math.Max(0,Math.Min(1000,(int)((index+value)/tracks.Count*1000)));});};if(mp3)Mp3Export.Render(p,target,options,_cancel.Token,progress);else AudioExport.Render(p,target,options,_cancel.Token,progress);}}catch(Exception ex){error=ex;}if(!IsDisposed)BeginInvoke((Action)delegate{_busy=false;_render.Enabled=true;_status.Text=error==null?"Master export complete: "+path:error is OperationCanceledException?"Cancelled; completed files were kept.":error.Message;});});_progress.Maximum=1000;}
 }

